import {
    _decorator,
    BoxCollider2D,
    Collider2D,
    Component,
    director,
    input,
    Input,
    EventKeyboard,
    JsonAsset,
    KeyCode,
    Node,
} from 'cc';
import { PlayerGridMove } from './GameArea/PlayerGridMove';
import { BattleTriggerOnContact } from './GameArea/BattleTriggerOnContact';
import { StoryDialoguePlayer, type ChoiceScript, type DialogueLineScript } from './StoryDialoguePlayer';
import { storyLog } from './storyLogger';

const { ccclass, property, executionOrder } = _decorator;

type MapNpcEvent = {
    eventId?: string;
    eventType?: string;
    order?: number;
    server?: { requirements?: unknown[] };
    client?: {
        dialogueScriptId?: string;
        choiceScriptId?: string;
        taskUiHint?: string;
    };
};

/**
 * 地图 NPC 交互：读取共享地图 Json（npcUid + events），在范围内按交互键触发对白/选项。
 * 与 BattleTriggerOnContact 同挂时，默认禁用战斗触发器，避免「先对话」被开战抢占。
 */
@ccclass('MapNpcInteract')
@executionOrder(-50)
export class MapNpcInteract extends Component {
    @property(JsonAsset)
    mapConfig: JsonAsset | null = null;

    @property(Node)
    uiRoot: Node | null = null;

    @property
    npcUid = '';

    @property({ tooltip: '本地调试：忽略 map JSON 里 server.requirements，便于验 UI 与对白' })
    skipServerRequirements = true;

    @property({ tooltip: '与 NPC 碰撞范围内按此键触发交互（默认 E）' })
    interactKey = KeyCode.KEY_E;

    @property({ tooltip: '为 true 时不再禁用同节点 BattleTriggerOnContact（纯战斗 NPC）' })
    letBattleTriggerHandleCombat = false;

    @property({
        tooltip: '兜底：与 BattleTriggerOnContact 一致，用 AABB 轮询重叠（物理事件未触发时仍可用）',
    })
    pollingEnabled = true;

    @property({ tooltip: '打印 [Story] 诊断日志（调通后可开）' })
    debugLog = false;

    /**
     * 与 map JSON `maxInteractDistance` 对齐的像素距离（纯距离兜底 + 与 AABB 配合时的“心距”上限）。
     * `_parseMap` 会用 JSON 值做上限收紧，不再做 1.5 倍放大。
     */
    @property
    interactDistanceFallbackPx = 120;

    /** 已在范围内时，允许心距略大于 R 仍保持“在范围内”，减少边界抖动（施密特触发） */
    @property
    interactReleaseHysteresisPx = 18;

    @property({ tooltip: '重复进入范围时，提示 Toast 的最小间隔（毫秒）' })
    interactHintMinIntervalMs = 8000;

    @property({ tooltip: '进入可交互范围时 Toast 提示文案' })
    interactHintText = '按 E 交谈';

    private _triggerBox: BoxCollider2D | null = null;
    private _playerTouching = false;
    private _playerMove: PlayerGridMove | null = null;
    /** 玩家任意 Collider2D（不限定 Box），用于 worldAABB 或兜底距离 */
    private _playerCollider: Collider2D | null = null;
    private _lastPlayerResolveAt = 0;
    private _loggedAabbFallback = false;
    private _lastOutOfRangeKeyLogAt = 0;
    private _lastRangeDiagLogAt = 0;
    private _lastInteractHintAt = 0;

    private _dialogueScripts: Record<string, DialogueLineScript> = {};
    private _choiceScripts: Record<string, ChoiceScript> = {};
    private _npcEvents: MapNpcEvent[] = [];

    /** 本地已完成的 eventId（会话内），用于按 order 推进多条 events，避免永远卡在第一条对白 */
    private readonly _localCompletedEventIds = new Set<string>();

    onLoad() {
        if (!this.letBattleTriggerHandleCombat) {
            const battle = this.getComponent(BattleTriggerOnContact);
            if (battle) battle.enabled = false;
        }
        this._triggerBox = this.getComponent(BoxCollider2D);
        input.on(Input.EventType.KEY_DOWN, this._onKeyDown, this);
        this._parseMap();
        this._resolveLocalPlayerOnce();
        this._ensureStoryPlayer();

        if (this.debugLog) {
            storyLog('info', 'MapNpcInteract.onLoad', {
                node: this.node?.name,
                npcUid: this.npcUid,
                hasMapConfig: Boolean(this.mapConfig?.json),
                eventCount: this._npcEvents.length,
                hasTriggerBox: Boolean(this._triggerBox),
                hasUiRoot: Boolean(this.uiRoot),
                battleTriggerLeftOn: this.letBattleTriggerHandleCombat,
                interactKey: this.interactKey,
                interactDistanceFallbackPx: this.interactDistanceFallbackPx,
            });
        }
    }

    onDestroy() {
        input.off(Input.EventType.KEY_DOWN, this._onKeyDown, this);
    }

    update() {
        if (this.pollingEnabled) {
            this._pollTouchOverlap();
        }
    }

    private _parseMap(): void {
        const raw = this.mapConfig?.json as Record<string, unknown> | null;
        if (!raw) {
            if (this.debugLog) {
                storyLog('warn', 'MapNpcInteract._parseMap: mapConfig 为空或尚未加载 json', {
                    node: this.node?.name,
                    npcUid: this.npcUid,
                });
            }
            return;
        }
        const client = (raw.client ?? {}) as Record<string, unknown>;
        this._dialogueScripts = (client.dialogueScripts ?? {}) as Record<string, DialogueLineScript>;
        this._choiceScripts = (client.choiceScripts ?? {}) as Record<string, ChoiceScript>;
        const npcs = (raw.npcs ?? []) as Array<{ npcUid?: string; events?: MapNpcEvent[] }>;
        const npc = npcs.find((n) => n.npcUid === this.npcUid);
        this._npcEvents = npc?.events ?? [];
        if (this.debugLog && !npc) {
            storyLog('warn', 'MapNpcInteract._parseMap: npcs 中未找到 npcUid', {
                npcUid: this.npcUid,
                known: npcs.map((n) => n.npcUid).filter(Boolean),
            });
        }

        const server = (raw.server ?? {}) as Record<string, unknown>;
        const anti = (server.antiCheat ?? {}) as Record<string, unknown>;
        const maxD = Number(anti.maxInteractDistance);
        if (Number.isFinite(maxD) && maxD > 0) {
            const before = this.interactDistanceFallbackPx;
            this.interactDistanceFallbackPx = Math.min(this.interactDistanceFallbackPx, maxD);
            if (this.debugLog) {
                storyLog('info', 'MapNpcInteract._parseMap: 交互距离已与 JSON maxInteractDistance 对齐（取小、不放大）', {
                    maxInteractDistance: maxD,
                    interactDistanceFallbackPxBefore: before,
                    interactDistanceFallbackPxAfter: this.interactDistanceFallbackPx,
                    releaseHysteresisPx: this.interactReleaseHysteresisPx,
                });
            }
        }
    }

    private _requirementsMet(reqs: unknown[] | undefined): boolean {
        if (this.skipServerRequirements) return true;
        if (!reqs?.length) return true;
        return false;
    }

    private _stableEventId(ev: MapNpcEvent): string {
        if (ev.eventId) return ev.eventId;
        return `${this.npcUid}#order_${ev.order ?? 0}`;
    }

    private _markEventDone(ev: MapNpcEvent): void {
        const id = this._stableEventId(ev);
        this._localCompletedEventIds.add(id);
        if (this.debugLog) {
            storyLog('info', 'MapNpcInteract: 事件已完成（本地推进）', {
                npcUid: this.npcUid,
                eventId: id,
                eventType: ev.eventType,
                completedCount: this._localCompletedEventIds.size,
            });
        }
    }

    /** 取第一个满足 requirements 且尚未本地完成的事件 */
    private _pickInteractEvent(): MapNpcEvent | null {
        const sorted = [...this._npcEvents].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
        for (const ev of sorted) {
            const reqs = ev.server?.requirements as unknown[] | undefined;
            if (!this._requirementsMet(reqs)) continue;
            if (this._localCompletedEventIds.has(this._stableEventId(ev))) continue;
            return ev;
        }
        return null;
    }

    private _ensureStoryPlayer(): StoryDialoguePlayer | null {
        if (!this.uiRoot) return null;
        let p = this.uiRoot.getComponent(StoryDialoguePlayer);
        if (!p) p = this.uiRoot.addComponent(StoryDialoguePlayer);
        return p;
    }

    private _onKeyDown = (e: EventKeyboard): void => {
        if (e.keyCode !== this.interactKey) return;
        if (!this.uiRoot) {
            if (this.debugLog) storyLog('warn', 'MapNpcInteract: 按了交互键但 uiRoot 未绑定', { node: this.node?.name });
            return;
        }
        if (!this._playerTouching) {
            const now = Date.now();
            if (this.debugLog && now - this._lastOutOfRangeKeyLogAt > 2000) {
                this._lastOutOfRangeKeyLogAt = now;
                storyLog('info', 'MapNpcInteract: 按了交互键但不在本 NPC 范围内（碰撞/AABB/距离兜底）', {
                    node: this.node?.name,
                    hasPlayerMove: Boolean(this._playerMove),
                    hasPlayerCollider: Boolean(this._playerCollider),
                });
            }
            return;
        }
        const existing = this.uiRoot.getComponent(StoryDialoguePlayer);
        if (existing?.isBlocking) {
            if (this.debugLog) storyLog('info', 'MapNpcInteract: 剧情占用中，忽略重复交互');
            return;
        }

        const ev = this._pickInteractEvent();
        if (!ev) {
            if (this.debugLog) {
                storyLog('info', 'MapNpcInteract: 无可推进事件（已全部完成、events 为空或 requirements 未满足）', {
                    npcUid: this.npcUid,
                    completedIds: Array.from(this._localCompletedEventIds),
                });
            }
            return;
        }

        const player = this._ensureStoryPlayer();
        if (!player) return;

        const client = ev.client ?? {};

        if (ev.eventType === 'dialog' && client.dialogueScriptId) {
            const scr = this._dialogueScripts[client.dialogueScriptId];
            if (scr) {
                if (this.debugLog) {
                    storyLog('info', 'MapNpcInteract: 开始对白', {
                        scriptId: client.dialogueScriptId,
                        speaker: scr.speaker,
                        eventId: this._stableEventId(ev),
                    });
                }
                player.startDialogue(scr, () => this._markEventDone(ev));
                return;
            }
            if (this.debugLog) {
                storyLog('warn', 'MapNpcInteract: dialogueScriptId 在 dialogueScripts 中不存在', {
                    scriptId: client.dialogueScriptId,
                });
            }
            return;
        }

        if (client.choiceScriptId) {
            const ch = this._choiceScripts[client.choiceScriptId];
            if (ch) {
                if (this.debugLog) {
                    storyLog('info', 'MapNpcInteract: 打开选项', {
                        choiceScriptId: client.choiceScriptId,
                        eventId: this._stableEventId(ev),
                    });
                }
                player.startChoice(
                    ch,
                    () => {
                        /* 选项已选，具体逻辑后续接服务端 */
                    },
                    () => this._markEventDone(ev),
                );
                return;
            }
        }

        if (ev.eventType === 'task' && client.taskUiHint) {
            player.showToast(client.taskUiHint, 3200);
            this._markEventDone(ev);
            return;
        }

        player.showToast(`未接入的 NPC 事件: ${ev.eventType ?? 'unknown'}`, 3200);
        this._markEventDone(ev);
    };

    private _resolveLocalPlayerOnce(): void {
        const now = Date.now();
        const resolved = Boolean(this._playerMove && this._playerCollider);
        // 仅在已解析到玩家时做 2s 节流；首帧/预制体晚到时必须每帧重试，否则会永久拿不到碰撞体
        if (resolved && this._lastPlayerResolveAt > 0 && now - this._lastPlayerResolveAt < 2000) return;
        this._lastPlayerResolveAt = now;
        try {
            const scene = director.getScene?.();
            this._playerMove = scene?.getComponentInChildren(PlayerGridMove) ?? null;
            const pNode = this._playerMove?.node;
            if (pNode) {
                const cols = pNode.getComponentsInChildren(Collider2D).filter((c) => c.enabled);
                this._playerCollider = cols[0] ?? null;
            } else {
                this._playerCollider = null;
            }
        } catch {
            this._playerMove = null;
            this._playerCollider = null;
        }
    }

    private _distanceToPlayer(): number {
        if (!this._playerMove?.node) return Number.POSITIVE_INFINITY;
        const a = this.node.worldPosition;
        const b = this._playerMove.node.worldPosition;
        return Math.hypot(a.x - b.x, a.y - b.y);
    }

    private _aabbValid(rect: { width: number; height: number } | null | undefined): boolean {
        return Boolean(rect && rect.width > 1e-6 && rect.height > 1e-6);
    }

    /** AABB 重叠（物理盒）；“可交互”心距仍受 interactDistanceFallbackPx 约束，避免盒过大吸住远处 */
    private _computeAabbOverlap(): boolean {
        const trig = this._triggerBox as unknown as Collider2D | null;
        if (!trig || !this._playerCollider) return false;
        const a = trig.worldAABB;
        const b = this._playerCollider.worldAABB;
        if (!this._aabbValid(a) || !this._aabbValid(b)) {
            if (this.debugLog && this._playerMove && !this._loggedAabbFallback) {
                this._loggedAabbFallback = true;
                storyLog('info', 'MapNpcInteract: AABB 无效，使用心距判定', {
                    aabbNpc: a ?? null,
                    aabbPlayer: b ?? null,
                });
            }
            return false;
        }
        return (
            a!.x < b!.x + b!.width &&
            a!.x + a!.width > b!.x &&
            a!.y < b!.y + b!.height &&
            a!.y + a!.height > b!.y
        );
    }

    private _pollTouchOverlap(): void {
        const prevTouching = this._playerTouching;
        this._resolveLocalPlayerOnce();
        const dist = this._distanceToPlayer();
        const R = this.interactDistanceFallbackPx;
        const RLeave = R + this.interactReleaseHysteresisPx;

        const aabbOverlap = this._computeAabbOverlap();
        const withinCenter = dist <= R;
        const withinLeave = dist <= RLeave;

        let hit = false;
        if (aabbOverlap) {
            hit = withinCenter;
        } else if (!prevTouching) {
            hit = withinCenter;
        } else {
            hit = withinLeave;
        }

        this._playerTouching = hit;

        if (prevTouching !== hit) {
            if (this.debugLog) {
                if (hit) {
                    storyLog('info', 'MapNpcInteract: inRange=true（边沿）', {
                        npcUid: this.npcUid,
                        node: this.node?.name,
                        dist,
                        thresholdPx: R,
                        aabbOverlap,
                    });
                } else {
                    storyLog('info', 'MapNpcInteract: inRange=false（边沿）', {
                        npcUid: this.npcUid,
                        node: this.node?.name,
                        dist,
                        thresholdPx: R,
                        releaseAtPx: RLeave,
                    });
                }
            }
            if (hit) {
                const p = this._ensureStoryPlayer();
                if (p && !p.isBlocking) {
                    const now = Date.now();
                    if (now - this._lastInteractHintAt >= this.interactHintMinIntervalMs) {
                        this._lastInteractHintAt = now;
                        p.showToast(this.interactHintText, 1600);
                    }
                }
            }
        }

        if (this.debugLog && !hit && this._playerMove?.node) {
            const near = dist < R * 2.2;
            const now = Date.now();
            if (near && now - this._lastRangeDiagLogAt > 3000) {
                this._lastRangeDiagLogAt = now;
                const npcWp = this.node.worldPosition;
                const plWp = this._playerMove.node.worldPosition;
                storyLog('info', 'MapNpcInteract: rangeDiag（未命中但较近）', {
                    npcUid: this.npcUid,
                    dist,
                    thresholdPx: R,
                    releaseAtPx: RLeave,
                    aabbOverlap: this._computeAabbOverlap(),
                    npcWorld: { x: npcWp.x, y: npcWp.y },
                    playerWorld: { x: plWp.x, y: plWp.y },
                    colliderCount: this._playerMove.node.getComponentsInChildren(Collider2D).filter((c) => c.enabled).length,
                });
            }
        }
    }
}
